  :localName "state_emptying_tank_B203";
  UML:doAction :act_set_pump_speed, :act_valve_pump_B203_on, :act_valve_pump_B204_on .

:act_set_pump_speed a UML:Action;
  rdfs:label "set pump_P101 speed";
  :localName "act_set_pump_speed";
  CPSMod:isChangedByActuator :pump_P101 .

:pump_P101 a VDI2206:Actuator;
  :localName "pump_P101" .

:act_valve_pump_B203_on a UML:Action;
  rdfs:label "open valve_pump_tank_B203";
  :localName "act_valve_pump_B203_on";
  CPSMod:isChangedByActuator :valve_pump_tank_B203 .

:valve_pump_tank_B203 a VDI2206:Actuator;
  :localName "valve_pump_tank_B203" .

:act_valve_pump_B204_on a UML:Action;
  rdfs:label "open valve_pump_tank_B204";
  :localName "act_valve_pump_B204_on";
  CPSMod:isChangedByActuator :valve_pump_tank_B204 .

:valve_pump_tank_B204 a VDI2206:Actuator;
  :localName "valve_pump_tank_B204" .

:state_bypass_emptying_tank_b203 a UML:State;
  rdfs:label "bypass emptying tank B203";
  :localName "state_bypass_emptying_tank_b203";
  UML:doAction :act_valve_pump_B203_on, :act_valve_pump_B204_on, :act_set_pump_speed_P102 .

:act_set_pump_speed_P102 a UML:Action;
  rdfs:label "set bypass pump P102 speed";
  :localName "act_set_pump_speed_P102";
  CPSMod:isChangedByActuator :bypass_pump_P102 .

:bypass_pump_P102 a VDI2206:Actuator;
  rdfs:label "should be activated if bypass is needed, because of fault on pipe 5/6 or pump_P101; connects tanks B201, B202, B203 with B204. Used instead of pump_P101";
  :localName "bypass_pump_P102" .

:state_filling_tank_B203 a UML:State;
  :localName "state_filling_tank_B203";
  UML:doAction :act_open_valve_in2 .

:act_open_valve_in2 a UML:Action;
  rdfs:label "open valve_in2";
  :localName "act_open_valve_in2";
  CPSMod:isChangedByActuator :valve_in2 .

:valve_in2 a VDI2206:Actuator;
  :localName "valve_in2" .

:state_emptying_tank_B202 a UML:State;
  :localName "state_emptying_tank_B202";
  UML:doAction :act_set_pump_speed, :act_valve_pump_B202_on, :act_valve_pump_B204_on .

:act_valve_pump_B202_on a UML:Action;
  rdfs:label "open valve_pump_tank_B202";
  :localName "act_valve_pump_B202_on";
  CPSMod:isChangedByActuator :valve_pump_tank_B202 .

:valve_pump_tank_B202 a VDI2206:Actuator;
  :localName "valve_pump_tank_B202" .

:state_bypass_emptying_tank_b202 a UML:State;
  rdfs:label "bypass emptying tank B202";
  :localName "state_bypass_emptying_tank_b202";
  UML:doAction :act_valve_pump_B202_on, :act_valve_pump_B204_on, :act_set_pump_speed_P102 .

:state_emptying_tank_B201 a UML:State;
  :localName "state_emptying_tank_B201";
  UML:doAction :act_set_pump_speed, :act_valve_pump_B201_on, :act_valve_pump_B204_on .

:act_valve_pump_B201_on a UML:Action;
  rdfs:label "open valve_pump_tank_B201";
  :localName "act_valve_pump_B201_on";
  CPSMod:isChangedByActuator :valve_pump_tank_B201 .

:valve_pump_tank_B201 a VDI2206:Actuator;
  :localName "valve_pump_tank_B201" .

:state_bypass_emptying_tank_b201 a UML:State;
  rdfs:label "bypass emptying tank B201";
  :localName "state_bypass_emptying_tank_b201";
  UML:doAction :act_valve_pump_B201_on, :act_valve_pump_B204_on, :act_set_pump_speed_P102 .

```


## EXAMPLES

